import base64, pathlib
b64 = ""
data = base64.b64decode(b64 + "=" * (4 - len(b64) % 4) if len(b64) % 4 else b64)
pathlib.Path("assets/logo/logo_white.png").write_bytes(data)
print(f"Written {len(data)} bytes")
from PIL import Image
img = Image.open("assets/logo/logo_white.png")
print(f"Size: {img.size}  Mode: {img.mode}")
